#!/usr/bin/env python3
"""Incremental owned-cmdline capture and phase-log evidence fix. No service/API/package operations.

Updates only process_control.py, smoke_checks.py, bench.py, tests/test_concurrent_deploy.py
and MANIFEST.sha256. Compatible pending BLINK_CONCURRENT_SHADOW state is deliberately
allowed so the corrected recovery code can be installed. It is never modified,
removed or signalled by this installer.
"""
from __future__ import annotations
import argparse
import base64
from contextlib import contextmanager
import datetime as dt
import fcntl
import hashlib
import json
import os
from pathlib import Path
import stat
import sys
import tempfile
import zlib

PAYLOAD = {'process_control.py': '', 'smoke_checks.py': '', 'bench.py': '', 'tests/test_concurrent_deploy.py': '', 'MANIFEST.sha256': ''}
BEFORE = {'process_control.py': 'c01e7b77c7489e33b75920d6e59998152d195f3aef3d7e0632da1e5831f08dc9', 'smoke_checks.py': '84cbc00b91984e2e0cd945456bbfe4ab50d1b46c0f4a0a30a261bec8fadc0fb3', 'bench.py': 'b321b91022f6024184da4da467deb017c92e22d43c72eb6d239a14a58677ae2d', 'tests/test_concurrent_deploy.py': '1806a5e9f77a817cef7949b8b45d0ff11e21cc53a3c9d55f29680ed8fdf87627', 'MANIFEST.sha256': '536f24577e838a0d2552c75b6bfaef4fca280c31516ce5f1a43459c1c3625df6'}
AFTER = {'process_control.py': 'd159c706055c9fc77e27db6c1a9ee09e1fd4e33dd81ba64361788252b906499f', 'smoke_checks.py': 'b34d240beec805b8fb2b4d456f792fc97cb78bf3885e362d08f58a664284ea96', 'bench.py': '3e282faf30b47012789d25950b2ba8c7db36380d7cfa28a73cc06ca78331f51d', 'tests/test_concurrent_deploy.py': '956c26d67bd71231a497f36233f91a630a72bd0b866312ace6310eae034db2aa', 'MANIFEST.sha256': 'c42e6c5412e1dc0511184a756deaeee769dcf32e67f631a1c9bf400d3cb1946c'}
DEFAULT = '/var/lib/jenkins/tomod/ops/local-llm-path-benchmark'
LOCKS = ('.verified-workflow.lock', '.benchmark.lock')

class Refuse(RuntimeError): pass

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def plain_path(path: Path) -> None:
    for part in [path, *path.parents]:
        if part.is_symlink(): raise Refuse('Symlink path refused: '+str(part))

def payload() -> dict[str, bytes]:
    files={k:zlib.decompress(base64.b64decode(v)) for k,v in PAYLOAD.items()}
    if set(files)!=set(AFTER): raise Refuse('Payload membership mismatch')
    for k,data in files.items():
        if sha(data)!=AFTER[k]: raise Refuse('Payload hash mismatch: '+k)
    return files

@contextmanager
def locks(target: Path, create: bool):
    fds=[]
    try:
        for name in LOCKS:
            p=target/name;plain_path(p)
            if not p.exists() and not create:continue
            fd=os.open(p,os.O_RDWR | (os.O_CREAT if create else 0) | os.O_NOFOLLOW,0o600);fds.append(fd)
            if not stat.S_ISREG(os.fstat(fd).st_mode):raise Refuse('Invalid lock file')
            try:fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError:raise Refuse('Workflow/benchmark/recovery is active; no file changes') from None
        yield
    finally:
        for fd in reversed(fds):os.close(fd)

def inspect_install(target: Path) -> tuple[str,list[str]]:
    plain_path(target)
    if not target.is_dir() or target.name!='local-llm-path-benchmark' or target.parent.name!='ops':
        raise Refuse('Expected existing ops/local-llm-path-benchmark test directory')
    pending=[];private=target/'.state';plain_path(private)
    if private.exists() and not private.is_dir():raise Refuse('Invalid private state directory')
    if private.exists():
        for jpath in private.glob('*/journal.json'):
            plain_path(jpath)
            if not jpath.is_file() or jpath.stat().st_size>2*1024*1024:raise Refuse('Invalid recovery journal')
            j=json.loads(jpath.read_text())
            if j.get('cleanup_pass') is True:continue
            if j.get('marker')!='BLINK_CONCURRENT_SHADOW' or j.get('state_dir')!=str(jpath.parent):
                raise Refuse('Pending journal is not a compatible concurrent-shadow run')
            pending.append(str(jpath.parent))
    manifest=target/'MANIFEST.sha256';plain_path(manifest)
    raw=manifest.read_bytes();digest=sha(raw)
    if digest==BEFORE['MANIFEST.sha256']:mode='before'
    elif digest==AFTER['MANIFEST.sha256']:mode='after'
    else:raise Refuse('Unrecognized tool manifest; do not overwrite unknown changes')
    seen=set()
    for line in raw.decode().splitlines():
        expected,rel=line.split('  ',1)
        if rel in seen or Path(rel).is_absolute() or '..' in Path(rel).parts:raise Refuse('Invalid manifest member')
        seen.add(rel);p=target/rel;plain_path(p)
        if not p.is_file() or sha(p.read_bytes())!=expected:raise Refuse('Current tool differs from manifest: '+rel)
    expected_map=BEFORE if mode=='before' else AFTER
    for rel,expected in expected_map.items():
        p=target/rel;plain_path(p)
        if not p.is_file() or sha(p.read_bytes())!=expected:raise Refuse('Unreviewed modified test file: '+rel)
    return mode,pending

def atomic_write(path: Path, data: bytes, previous) -> None:
    plain_path(path)
    fd,tmp=tempfile.mkstemp(prefix='.owned-capture-',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(data);f.flush();os.fsync(f.fileno())
            os.fchmod(f.fileno(),stat.S_IMODE(previous.st_mode))
            if (previous.st_uid,previous.st_gid)!=(os.geteuid(),os.getegid()):
                os.fchown(f.fileno(),previous.st_uid,previous.st_gid)
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)

def update(target: Path, *, apply: bool=False) -> dict:
    files=payload();plain_path(target)
    if not target.is_dir():raise Refuse('Test directory missing')
    with locks(target,create=apply):
        mode,pending=inspect_install(target)
        result={'pass':True,'mode':'already_current' if mode=='after' else ('apply' if apply else 'check_only'),
                'managed_files_changed':0,'service_actions':0,'existing_snapshot_changes':0,
                'pending_recovery_preserved':pending,'recovery_performed':False}
        if mode=='after' or not apply:return result
        tag=dt.datetime.now(dt.timezone.utc).strftime('%Y%m%d-%H%M%S-%f')
        backup=target/'backups'/('owned-capture-'+tag);plain_path(backup);backup.mkdir(parents=True,mode=0o700)
        old={};states={};written=[]
        for rel in files:
            p=target/rel;old[rel]=p.read_bytes();states[rel]=p.stat()
            if sha(old[rel])!=BEFORE[rel]:raise Refuse('Concurrent tool edit before backup: '+rel)
            q=backup/rel;q.parent.mkdir(parents=True,exist_ok=True);q.write_bytes(old[rel]);q.chmod(0o600)
        order=sorted(files,key=lambda rel:(rel=='MANIFEST.sha256',rel))
        try:
            for rel in order:
                p=target/rel
                if sha(p.read_bytes())!=BEFORE[rel]:raise Refuse('Concurrent tool edit before replace: '+rel)
                atomic_write(p,files[rel],states[rel]);written.append(rel)
            mode,_=inspect_install(target)
            if mode!='after':raise Refuse('Post-update manifest mismatch')
        except BaseException:
            failed=[]
            for rel in reversed(written):
                try:atomic_write(target/rel,old[rel],states[rel])
                except Exception:failed.append(rel)
            if failed:
                (backup/'ROLLBACK_FAILED.json').write_text(json.dumps({'paths':failed}))
                raise Refuse('Recovery tool update rollback failed; preserve backup and do not run tests') from None
            raise
        result.update(managed_files_changed=len(files),backup=str(backup))
        (backup/'update-result.json').write_text(json.dumps(result,indent=2)+'\n')
        return result

def main() -> int:
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--target',default=DEFAULT)
    mode=ap.add_mutually_exclusive_group(required=True)
    mode.add_argument('--check-only',action='store_true');mode.add_argument('--apply',action='store_true')
    args=ap.parse_args();os.umask(0o077)
    print(json.dumps(update(Path(args.target).absolute(),apply=args.apply),ensure_ascii=False,indent=2));return 0

if __name__=='__main__':
    try:raise SystemExit(main())
    except (Refuse,OSError,ValueError) as exc:
        print('[REFUSED]',str(exc),file=sys.stderr);raise SystemExit(1)
    except KeyboardInterrupt:
        print('[INTERRUPTED] No service operations; inspect backup/manifest before continuing',file=sys.stderr);raise SystemExit(130)
